// 流程审批时获取合同信息-目的不是回显，而是获取信息里面的参数status、examineStatus传入最终保存合同信息的接口
getContractInfo_check_auditing(){
  if (this.initializationPromise) return this.initializationPromise
  if (!this.thatInstance || typeof this.thatInstance.getValues !== 'function') {
    this.initWaitingForForm = true
    return Promise.resolve(null)
  }
  this.initializationError = null
  const promise = (async () => {
    console.log('getContractInfo_check_auditing')
    if (!this.businessId) throw new Error('审批合同缺少业务 ID，已阻止保存')
    const res = await this.$axios.post(
      Api.contractManage.contractInfo.getContractDetail,
      { data: { id: this.businessId } }
    )
    if (!res?.isSuccess || !res.data) {
      throw new Error(res?.message || '无法读取合同当前状态，已阻止保存')
    }
    // 修改接口要求沿用目标当前合同状态；不能用固定默认值覆盖已完成的评审状态。
    this.currentContractInfo = res.data
    this.contractList = [res.data]

    const formVal = this.thatInstance.getValues() || {}
    const contractTypeTree = await this.getContractTypeTree()
    const classId = formVal.classificationId instanceof Array
      ? (formVal.classificationId.length ? formVal.classificationId[formVal.classificationId.length - 1] : '')
      : formVal.classificationId
    const objResult = getObjById(contractTypeTree, classId, 'children')
    if (!formVal['classificationId__virtualName'] && objResult?.name) {
      this.thatInstance.setData({ 'classificationId__virtualName': objResult.name })
    }
    // 表单实例已经就绪时立即回写，避免固定延时覆盖后续用户或组件写入。
    if (Object.prototype.hasOwnProperty.call(formVal, 'seeFile')) {
      this.thatInstance.setData({ 'seeFile': formVal.seeFile })
    }
    const fileRes = await this.getFileByContractId(this.businessId)
    this.contractRefFileList = fileRes?.contractRefFileTypeApiVo?.contractRefFileTypeVos || []
    return this.currentContractInfo
  })()
  this.initializationPromise = promise
  promise.catch(error => {
    this.initializationError = error
    console.error('合同审批初始化失败', error)
    this.$message?.error(String(error?.message ?? error))
  }).finally(() => {
    if (this.initializationPromise === promise) this.initializationPromise = null
  })
  return promise
},
