// 合同合规性评审业务逻辑：表单整体分为合同信息+手续文件+合同文件+合规审查日志
async contractBusiness(generateFormRefs,that,flag,type){
  console.log('contractBusiness')
  this.batchCode = that.batchCode
  let isNeedValidate = type !== 'no_pass' && that.clickMethod !== 'draft'
  try {
    if (!this.isFlowInitiate) {
      // 初始化收尾向表单回写可能引起本组件重建，jsonData 接线只发一次，重建实例收不到；
      // 分发时表单实例就在第一个参数上，仍未初始化就就地补一次有界初始化。
      if (!this.initializationPromise && !this.initializationError && !this.currentContractInfo?.id) {
        this.initFormInstance(generateFormRefs)
      }
      if (this.initializationPromise) await this.initializationPromise
      if (this.initializationError) throw this.initializationError
      if (!this.currentContractInfo?.id) throw new Error('合同当前状态未读取成功，已阻止提交')
    }
    await generateFormRefs.getData(isNeedValidate)
    const value = generateFormRefs.getValues() || {}
    await this.deleteLegalProcedureFile(value, generateFormRefs)
    const saveResult = await this.saveOrModifyContractInfo(value, that, type)
    const contractId = this.formPage
      ? this.businessId
      : (this.isFlowInitiate ? saveResult?.id : this.businessId)
    if (!contractId) throw new Error('合同保存成功但未返回合同 ID，已阻止流程提交')
    that.businessId = contractId
    await this.legalProcedureBind(value, contractId, generateFormRefs)

    if (!this.isFlowInitiate) {
      if (that.isReInitiate) {
        if (that.isDraftInReInitiateStatus) that.handleSaveDraft()
        else that.handleRePostSubmit(flag, type)
      } else {
        that.handleSubmitCheck(flag, type)
      }
    } else {
      that.enterpriseHandleSubmit(flag)
    }
  } catch (error) {
    that.submitLoading = false
    that.noSubmitLoading = false
    const message = String(error?.message ?? error)
    console.error('合同业务处理失败，已阻止流程提交', error)
    this.$message?.error(message)
  }
},
