// 删除未选中的手续文件；所有解除关系请求完成后才允许保存合同。
async deleteLegalProcedureFile(formVal,generateFormRefs){
  const contractTalkName = formVal.contractTalk
  const objList = {
    '公开招标':'GKzhaobiao', '非公开挂网':'FGKguawang', '非挂网方式':'FGWfangshi',
    '直签':'zhiqian', '单一来源采购':'DYLYcaigou', '内部采购':'NBcaigou',
    '框采':'kuangcai', '其他':'QTwenjian'
  }
  const clearFileObj = {}
  const needUnbindFileObj = {}
  const copyFormVal = JSON.parse(JSON.stringify(formVal))
  for (const key of Object.keys(objList)) {
    if (key === contractTalkName) continue
    const prefix = objList[key]
    for (const field of Object.keys(formVal)) {
      if (field.includes(prefix) && Array.isArray(formVal[field]) && formVal[field].length > 0) {
        needUnbindFileObj[field] = JSON.parse(JSON.stringify(formVal[field]))
        clearFileObj[field] = []
        formVal[field] = []
      }
    }
  }
  generateFormRefs.setData(clearFileObj)
  const pending = []
  if (Object.keys(needUnbindFileObj).length && this.contractRefFileList.length) {
    for (const item of this.contractRefFileList) {
      if (item.fileType === '合同文件' || !needUnbindFileObj[item.fileType]) continue
      const fileIds = needUnbindFileObj[item.fileType]
        .map(file => file.data?.fileId || file.data?.id)
        .filter(Boolean)
      if (fileIds.length) pending.push(this.deleteFileRelation(item.bizId, fileIds))
    }
  }
  await Promise.all(pending)
},
// 业务-合同合规手续文件绑定合同id
async legalProcedureBind(formVal,contractId,generateFormRefs){
  const contractTalkName = formVal.contractTalk
  const objList = {
    '公开招标':'GKzhaobiao', '非公开挂网':'FGKguawang', '非挂网方式':'FGWfangshi',
    '直签':'zhiqian', '单一来源采购':'DYLYcaigou', '内部采购':'NBcaigou',
    '框采':'kuangcai', '其他':'QTwenjian'
  }
  const needBindFileList = {}
  const contractRefFileTypeVos = []
  const pending = []
  for (const field of Object.keys(formVal)) {
    if (field.includes(objList[contractTalkName]) && Array.isArray(formVal[field]) && formVal[field].length > 0) {
      needBindFileList[field] = formVal[field]
    }
  }
  for (const field of Object.keys(needBindFileList)) {
    const existing = this.contractRefFileList.find(item => item.fileType === field)
    const temporaryBizId = existing?.bizId || generateRandomId(32)
    const fileIds = needBindFileList[field]
      .map(item => item.data?.fileId || item.data?.id)
      .filter(Boolean)
    if (fileIds.length) pending.push(this.saveBatchFile(temporaryBizId, fileIds))
    contractRefFileTypeVos.push({ bizId: temporaryBizId, fileType: field })
  }
  const sealFiles = Array.isArray(formVal.sealContractFile) ? formVal.sealContractFile : []
  if (sealFiles.length > 0) {
    const existing = this.contractRefFileList.find(item => item.fileType === 'sealContractFile')
    const temporaryBizId = existing?.bizId || generateRandomId(32)
    const fileIds = sealFiles.map(item => item.data?.fileId || item.data?.id).filter(Boolean)
    if (fileIds.length) pending.push(this.saveBatchFile(temporaryBizId, fileIds))
    contractRefFileTypeVos.push({ bizId: temporaryBizId, fileType: 'sealContractFile' })
  }
  const contractExisting = this.contractRefFileList.find(item => item.fileType === '合同文件')
  contractRefFileTypeVos.push({
    bizId: contractExisting?.bizId || generateRandomId(32),
    fileType: '合同文件'
  })
  // 文件批量关系成功后再保存合同关系，最后才允许主流程动作。
  await Promise.all(pending)
  await this.saveContractRefFile(contractId, contractRefFileTypeVos)
},
